async function gcpFetch(
  http: Http,
  url: string,
  init?: RequestInit,
): Promise<Response> {
  for (let attempt = 0;; attempt++) {
    let resp: Response | undefined;
    // The limiter paces first attempts. Retries are not counted: each one
    // already waits out a backoff and is capped at MAX_RETRIES per request, but
    // they still count against Google's quota, so keep maxRequestsPerMinute
    // below the real limit with headroom for retry bursts.
    if (attempt === 0) await http.limit?.();
    try {
      resp = await http.fetchFn(url, init);
    } catch (err) {
      if (attempt >= MAX_RETRIES) throw err;
    }
    if (resp && (!RETRY_STATUSES.has(resp.status) || attempt >= MAX_RETRIES)) {
      return resp;
    }
    const retryAfter = Number(resp?.headers.get("retry-after"));
    // Quota (429) windows last a minute, so back off harder than for 5xx.
    const base = resp?.status === 429 ? RATE_LIMIT_DELAY_MS : BASE_DELAY_MS;
    const delay = Number.isFinite(retryAfter) && retryAfter > 0
      ? Math.min(retryAfter * 1000, 60_000)
      : Math.min(base * 2 ** attempt, 30_000);
    await resp?.body?.cancel();
    await http.sleepFn(delay);
  }
}

